import { Controller, Get, Post, Put, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const MAX_NAME_LENGTH = 200;

interface Db {
  query(sql: string, params?: Record<string, unknown>): Promise<Record<string, unknown>[]>;
  execute(sql: string, params?: Record<string, unknown>): Promise<number>;
}

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function idOf(value: unknown, label: string): number {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
    return value;
  }
  if (typeof value === 'string' && /^[0-9]+$/.test(value) && Number(value) > 0) {
    return Number(value);
  }
  throw invalid(label + ' 값이 올바르지 않습니다.');
}

function nameOf(value: unknown): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw invalid('대화방 이름을 입력해 주세요.');
  }
  if (value.trim().length > MAX_NAME_LENGTH) {
    throw invalid('대화방 이름은 ' + MAX_NAME_LENGTH + '자 이내로 입력해 주세요.');
  }
  return value.trim();
}

function memberIdsOf(value: unknown): number[] {
  if (!Array.isArray(value)) {
    throw invalid('참여 임직원 목록이 올바르지 않습니다.');
  }
  const ids = value.map((v) => idOf(v, '참여 임직원 ID'));
  return Array.from(new Set(ids));
}

function numberQuery(value: unknown, fallback: number, label: string): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    throw invalid(label + ' 값이 올바르지 않습니다.');
  }
  return n;
}

async function ensureEmployees(db: Db, ids: number[]): Promise<void> {
  for (const id of ids) {
    const rows = await db.query(
      'SELECT employee_id AS "employeeId" FROM employee WHERE employee_id = CAST(:id AS bigint)',
      { id },
    );
    if (rows.length === 0) {
      throw new ApiError(404, 'NOT_FOUND', '존재하지 않는 임직원이 참여자에 포함되어 있습니다.');
    }
  }
}

async function addMembers(db: Db, chatRoomId: number, ids: number[]): Promise<void> {
  for (const employeeId of ids) {
    await db.execute(
      'INSERT INTO chat_room_member (chat_room_id, employee_id, created_at, updated_at) '
        + 'VALUES (CAST(:chatRoomId AS bigint), CAST(:employeeId AS bigint), now(), now())',
      { chatRoomId, employeeId },
    );
  }
}

async function ownRoom(db: Db, chatRoomId: number, userId: string): Promise<void> {
  const rows = await db.query(
    'SELECT chat_room_id AS "chatRoomId" FROM chat_room '
      + 'WHERE chat_room_id = CAST(:chatRoomId AS bigint) AND creator_id = CAST(:userId AS bigint)',
    { chatRoomId, userId },
  );
  if (rows.length === 0) {
    throw new ApiError(404, 'CHAT_ROOM_NOT_FOUND', '대화방이 없거나 본인이 등록한 대화방이 아닙니다.');
  }
}

function pathIdOf(raw: string | undefined): number {
  if (raw === undefined || !/^[0-9]+$/.test(raw) || Number(raw) <= 0) {
    throw new ApiError(404, 'CHAT_ROOM_NOT_FOUND', '대화방이 없거나 본인이 등록한 대화방이 아닙니다.');
  }
  return Number(raw);
}

@Controller('api/v1')
export class FnSfr03601Controller {
  @Get('/chat-rooms')
  async listChatRooms(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const page = numberQuery(query['page'], 0, '쪽');
    const requested = numberQuery(query['size'], DEFAULT_SIZE, '크기');
    const size = Math.min(Math.max(requested, 1), MAX_SIZE);
    return transaction(async (db) => {
      // 참여 중인 대화방(참여자이거나 등록자)만 조회한다
      const where = 'FROM chat_room r WHERE r.creator_id = CAST(:userId AS bigint) '
        + 'OR EXISTS (SELECT 1 FROM chat_room_member m '
        + 'WHERE m.chat_room_id = r.chat_room_id AND m.employee_id = CAST(:userId AS bigint))';
      const items = await db.query(
        'SELECT r.chat_room_id AS "chatRoomId", r.name AS "name" ' + where
          + ' ORDER BY r.chat_room_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { userId: user.id, size, offset: page * size },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" ' + where,
        { userId: user.id },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/chat-rooms')
  @HttpCode(200)
  async createChatRoom(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const name = nameOf(data['name']);
    const memberIds = memberIdsOf(data['memberIds']);
    const creatorId = idOf(user.id, '사용자 ID');
    return transaction(async (db) => {
      await ensureEmployees(db, memberIds);
      const rows = await db.query(
        'INSERT INTO chat_room (name, creator_id, created_at, updated_at) '
          + 'VALUES (:name, CAST(:userId AS bigint), now(), now()) '
          + 'RETURNING chat_room_id AS "chatRoomId", name AS "name"',
        { name, userId: user.id },
      );
      const room = rows[0];
      const chatRoomId = Number(room['chatRoomId']);
      // 등록자도 참여자에 포함한다
      const all = Array.from(new Set([creatorId, ...memberIds]));
      await addMembers(db, chatRoomId, all);
      return { chatRoomId, name: room['name'] };
    });
  }

  @Put('/chat-rooms/:chatRoomId')
  async updateChatRoom(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const chatRoomId = pathIdOf(req.params['chatRoomId']);
    const data = checks.inputOf(req.body);
    const name = nameOf(data['name']);
    const hasMembers = data['memberIds'] !== undefined && data['memberIds'] !== null;
    const memberIds = hasMembers ? memberIdsOf(data['memberIds']) : [];
    const creatorId = idOf(user.id, '사용자 ID');
    return transaction(async (db) => {
      await ownRoom(db, chatRoomId, user.id);
      if (hasMembers) {
        await ensureEmployees(db, memberIds);
      }
      const rows = await db.query(
        'UPDATE chat_room SET name = :name, updated_at = now() '
          + 'WHERE chat_room_id = CAST(:chatRoomId AS bigint) '
          + 'RETURNING chat_room_id AS "chatRoomId", name AS "name"',
        { name, chatRoomId },
      );
      if (hasMembers) {
        await db.execute(
          'DELETE FROM chat_room_member WHERE chat_room_id = CAST(:chatRoomId AS bigint)',
          { chatRoomId },
        );
        const all = Array.from(new Set([creatorId, ...memberIds]));
        await addMembers(db, chatRoomId, all);
      }
      return { chatRoomId: Number(rows[0]['chatRoomId']), name: rows[0]['name'] };
    });
  }

  @Delete('/chat-rooms/:chatRoomId')
  async deleteChatRoom(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const chatRoomId = pathIdOf(req.params['chatRoomId']);
    return transaction(async (db) => {
      await ownRoom(db, chatRoomId, user.id);
      await db.execute(
        'DELETE FROM chat_room_member WHERE chat_room_id = CAST(:chatRoomId AS bigint)',
        { chatRoomId },
      );
      await db.execute(
        'DELETE FROM chat_room WHERE chat_room_id = CAST(:chatRoomId AS bigint)',
        { chatRoomId },
      );
      return {};
    });
  }
}

