import { useState } from 'react';
import {
  call,
  useData,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  LookupSelect,
  RefName,
  Tiles,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const PAGE_SIZE = 20;

type Mode = { kind: 'create' } | { kind: 'edit'; room: Row } | { kind: 'delete'; room: Row } | null;

export default function FnSfr03601Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode>(null);
  const [name, setName] = useState('');
  const [memberIds, setMemberIds] = useState<(number | string)[]>([]);
  const [picked, setPicked] = useState<number | string>('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/chat-rooms', role, undefined, { page, size: PAGE_SIZE }),
    [page, role],
  );

  const rows = data?.items ?? [];

  function open(next: Mode) {
    setName(next && next.kind === 'edit' ? String(next.room['name'] ?? '') : '');
    setMemberIds([]);
    setPicked('');
    setMode(next);
  }

  function addMember() {
    if (picked === '' || memberIds.includes(picked)) {
      return;
    }
    setMemberIds([...memberIds, picked]);
    setPicked('');
  }

  function removeMember(id: number | string) {
    setMemberIds(memberIds.filter((m) => m !== id));
  }

  function checkName() {
    if (String(name).trim() === '') {
      throw new Error('대화방 이름을 입력해 주세요.');
    }
  }

  async function create() {
    checkName();
    if (memberIds.length === 0) {
      throw new Error('참여 임직원을 한 명 이상 선택해 주세요.');
    }
    await call('POST', '/chat-rooms', role, { name: String(name).trim(), memberIds });
    notify('개인 대화방을 등록했습니다.');
    setMode(null);
    setPage(0);
    reload();
  }

  async function update(room: Row) {
    checkName();
    const body: Row = { name: String(name).trim() };
    if (memberIds.length > 0) {
      body['memberIds'] = memberIds;
    }
    await call('PUT', '/chat-rooms/' + String(room['chatRoomId']), role, body);
    notify('개인 대화방을 수정했습니다.');
    setMode(null);
    reload();
  }

  async function remove(room: Row) {
    await call('DELETE', '/chat-rooms/' + String(room['chatRoomId']), role);
    notify('개인 대화방을 삭제했습니다.');
    setMode(null);
    reload();
  }

  const memberPicker = (
    <Field label="참여 임직원 ID 목록" required={mode?.kind === 'create'} wide hint={mode?.kind === 'edit' ? '비워 두면 참여자는 바꾸지 않습니다.' : undefined}>
      <div>
        <LookupSelect table="employee" role={role} value={picked} onChange={setPicked} placeholder="임직원 선택" />
        <button type="button" onClick={addMember}>추가</button>
        <ul>
          {memberIds.map((id) => (
            <li key={String(id)}>
              <RefName table="employee" role={role} value={id} />
              <button type="button" onClick={() => removeMember(id)}>제거</button>
            </v>
          ))}
        </ul>
      </div>
    </Field>
  );

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>참여 대화방</h2>
        <Tiles items={[['대화방 수', data?.total ?? 0]]} />
      </section>
      <section className="box span-8">
        <h2>대화방 목록</h2>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total}>
          <button type="button" onClick={() => open({ kind: 'create' })}>대화방 등록</button>
        </Band>
        <DataTable
          columns={[
            { key: 'chatRoomId', label: '대화방 ID' },
            { key: 'name', label: '대화방 이름' },
            {
              key: 'actions',
              label: '관리',
              render: (row: Row) => (
                <span>
                  <button type="button" onClick={() => open({ kind: 'edit', room: row })}>수정</button>
                  <button type="button" onClick={() => open({ kind: 'delete', room: row })}>삭제</button>
                </span>
              ),
            },
          ]}
          rows={rows}
          empty="참여 중인 대화방이 없습니다."
        />
        <Pager page={page} size={data?.size ?? PAGE_SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {mode && mode.kind === 'create' ? (
        <Drawer title="개인 대화방 등록" onClose={() => setMode(null)}>
          <Form onSubmit={create} submit="등록">
            <Field label="대화방 이름" required wide>
              <TextInput value={name} onChange={setName} />
            </Field>
            {memberPicker}
          </Form>
        </Drawer>
      ) : null}
      {mode && mode.kind === 'edit' ? (
        <Drawer title="개인 대화방 수정" onClose={() => setMode(null)}>
          <Form onSubmit={() => update(mode.room)} submit="수정">
            <Field label="대화방 이름" required wide>
              <TextInput value={name} onChange={setName} />
            </Field>
            {memberPicker}
          </Form>
        </Drawer>
      ) : null}
      {mode && mode.kind === 'delete' ? (
        <Drawer title="개인 대화방 삭제" onClose={() => setMode(null)}>
          <Form onSubmit={() => remove(mode.room)} submit="삭제" danger note={'"' + String(mode.room['name']) + '" 대화방을 삭제합니다.'} />
        </Drawer>
      ) : null}
    </div>
  );
}
